'use strict';
const $=id=>document.getElementById(id);
const zones=[{name:'風そよぐ草原',sub:'LV.1–3 · はじまりの冒険',icon:'♧',color:'#72967e',kills:4,boss:'草原の番人'},{name:'月影の遺跡',sub:'LV.3–5 · 古き星の記憶',icon:'♜',color:'#667c99',kills:4,boss:'月影のゴーレム'},{name:'紅蓮の火山',sub:'LV.5–7 · 炎の試練',icon:'♨',color:'#a87362',kills:4,boss:'紅蓮の竜'}];
const gear={twig:{name:'旅人の剣',type:'weapon',value:0,icon:'⚔',price:0},iron:{name:'鉄のつるぎ',type:'weapon',value:6,icon:'⚔',price:70},star:{name:'星銀のつるぎ',type:'weapon',value:14,icon:'⚔',price:220},cloth:{name:'旅人の服',type:'armor',value:0,icon:'♢',price:0},leather:{name:'革のよろい',type:'armor',value:4,icon:'♢',price:55},moon:{name:'月守りのよろい',type:'armor',value:10,icon:'♢',price:180}};
const consumables={herb:{name:'いやし草',desc:'HPを45回復',icon:'🌿',price:12},ether:{name:'星のしずく',desc:'MPを18回復',icon:'💧',price:22},potion:{name:'生命の霊薬',desc:'HPをすべて回復',icon:'⚱',price:40}};
const skillList=[{id:'flame',name:'火花の魔法',lv:2,cost:4,desc:'防御を貫く炎の攻撃',icon:'✹'},{id:'heal',name:'星のいやし',lv:3,cost:5,desc:'HPを55回復',icon:'✧'},{id:'slash',name:'流星斬り',lv:5,cost:8,desc:'攻撃力2.4倍の一撃',icon:'⚔'},{id:'nova',name:'星光の魔法',lv:7,cost:12,desc:'防御を貫く強力な魔法',icon:'✵'}];
const initial=()=>({v:1,lv:1,xp:0,hp:80,mp:20,gold:30,weapon:'twig',armor:'cloth',owned:['twig','cloth'],items:{herb:3,ether:1,potion:0},zone:0,kills:[0,0,0],cleared:[false,false,false],total:0,claimed:false,enemy:null,turn:1,log:['はじまりの村を出発した。草原で腕を磨こう。'],village:false});
let state=initial(),tab='bag',busy=false,sound=false,ctx;
try{const raw=JSON.parse(localStorage.getItem('starlight-rpg-v1'));if(raw&&raw.v===1&&Array.isArray(raw.kills)&&Number.isFinite(raw.hp))state=raw}catch{}
const maxhp=()=>80+(state.lv-1)*17;const maxmp=()=>20+(state.lv-1)*4;const attack=()=>13+(state.lv-1)*4+gear[state.weapon].value;const defense=()=>4+(state.lv-1)*2+gear[state.armor].value;const threshold=()=>25+state.lv*15;
function save(){try{localStorage.setItem('starlight-rpg-v1',JSON.stringify(state));$('saveStatus').textContent='オートセーブ済み'}catch{$('saveStatus').textContent='保存できません（ブラウザ設定）'}}
function log(t){state.log.unshift(t);state.log=state.log.slice(0,35)}
function beep(kind=0){if(!sound)return;try{ctx??=new (window.AudioContext||window.webkitAudioContext)();const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.setValueAtTime(kind?650:320,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(kind?950:100,ctx.currentTime+.12);g.gain.setValueAtTime(.045,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.2);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.2)}catch{}}
function landscape(){const z=state.zone;const sky=z===0?'#99b8a5':z===1?'#738099':'#b17c68',mount=z===0?'#507b6e':z===1?'#4c5d79':'#735559';let trees='';for(let i=0;i<16;i++){const x=i*49-25,y=170+(i%3)*16;trees+=`<path d="M${x} ${y+100}l22 -93 24 93h-18v30h-13v-30z" fill="${z===2?'#4c474a':'#254e49'}"/>`}
return `<svg viewBox="0 0 800 420" preserveAspectRatio="xMidYMid slice"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="${sky}"/><stop offset="1" stop-color="#dbd2ab"/></linearGradient><linearGradient id="ground" x2="0" y2="1"><stop stop-color="${mount}"/><stop offset="1" stop-color="#243f3b"/></linearGradient></defs><rect width="800" height="420" fill="url(#sky)"/><circle cx="580" cy="90" r="33" fill="#f5e8b9" opacity=".8"/><path d="M0 220L130 110 215 185 335 70 455 198 570 118 690 203 800 135V420H0" fill="${mount}" opacity=".4"/><path d="M0 260L90 192 200 251 350 160 470 250 650 171 800 265V420H0" fill="${mount}" opacity=".8"/><path d="M0 280Q190 225 400 280T800 260V420H0" fill="url(#ground)"/>${z===1?'<g fill="#39485c"><path d="M110 285V140h25v145m-28-145h31v-10h-31M620 282V130h26v152m-30-152h34v-13h-34"/><path d="M100 130L370 96 660 117v15L370 116 100 146z"/></g>':trees}<path d="M335 420Q490 340 400 283Q510 330 520 420" fill="#b6b08a" opacity=".35"/><g fill="#e8d797" opacity=".7">${Array.from({length:20},(_,i)=>`<circle cx="${(i*137)%790}" cy="${290+(i*29)%125}" r="${1+i%2}"/>`).join('')}</g></svg>`}
function monster(e){const color=e.boss?['#d5aa68','#9a99bf','#c9755e'][state.zone]:['#88bc8a','#9cacc2','#d5a06b'][state.zone];if(e.boss)return `<svg viewBox="0 0 180 180"><path d="M57 82L8 35 20 111 66 120M120 82l52-47-15 82-41 4" fill="${color}" stroke="#283f43" stroke-width="4"/><path d="M48 144Q26 105 64 62L55 28 82 46 103 42 126 25 124 67Q161 129 131 151Z" fill="${color}" stroke="#283f43" stroke-width="4"/><path d="M62 145l-10 22h26l8-20m28-2 7 22h28l-16-23" fill="${color}" stroke="#283f43" stroke-width="4"/><path d="M68 84l17 8m17-1 17-10" stroke="#243e43" stroke-width="8"/><path d="M80 119l12 10 14-10" fill="none" stroke="#243e43" stroke-width="4"/><path d="M86 99l-13 43h43l-18-43" fill="#e9d6ae" opacity=".7"/></svg>`;
return `<svg viewBox="0 0 180 180"><ellipse cx="90" cy="158" rx="65" ry="9" fill="#163f3c" opacity=".3"/><path d="M28 125Q24 93 52 79Q64 69 90 31Q107 70 129 79Q161 94 154 127Q147 157 90 157Q35 157 28 125" fill="${color}" stroke="#315951" stroke-width="4"/><path d="M45 107Q48 86 66 88" fill="none" stroke="#edf9d0" stroke-width="7" stroke-linecap="round" opacity=".6"/><ellipse cx="70" cy="115" rx="6" ry="9" fill="#243d3f"/><ellipse cx="112" cy="115" rx="6" ry="9" fill="#243d3f"/><path d="M80 132q10 8 21-1" fill="none" stroke="#334e47" stroke-width="3" stroke-linecap="round"/></svg>`}
function meter(label,value,max,cls=''){return `<div><div class="meter-head"><span>${label}</span><strong>${value} <span style="opacity:.45">/ ${max}</span></strong></div><div class="bar ${cls}"><i style="width:${Math.min(100,value/max*100)}%"></i></div></div>`}
function btn(text,action,sub='',disabled=false){return `<button data-action="${action}" ${disabled?'disabled':''}>${text}${sub?`<small>${sub}</small>`:''}</button>`}
function render(){const e=state.enemy,z=zones[state.zone];$('level').textContent='Lv. '+state.lv;$('stats').innerHTML=meter('HP',state.hp,maxhp())+meter('MP',state.mp,maxmp(),'mp')+meter('EXP',state.xp,threshold(),'exp');$('attributes').innerHTML=`<div>攻撃力<b>${attack()}</b></div><div>守備力<b>${defense()}</b></div><div>討伐数<b>${state.total}</b></div>`;$('equipment').innerHTML=`<p>⚔ 武器<span>${gear[state.weapon].name}</span></p><p>♢ 防具<span>${gear[state.armor].name}</span></p>`;$('gold').textContent=state.gold+' G';$('location').textContent='⌖ '+(state.village?'はじまりの村':z.name);$('phase').textContent=e?(e.boss?'BOSS BATTLE':'BATTLE'):state.village?'VILLAGE':'EXPLORATION';$('landscape').innerHTML=landscape();$('enemy').innerHTML=e?monster(e)+`<div class="enemyname">${e.name}${meter('HP',e.hp,e.max)}</div>`:'';$('sceneCaption').innerHTML=e?'':state.village?'旅の準備を、ここで。<small>宿屋でひと休みして、次の冒険へ。</small>':state.cleared.every(Boolean)?'世界に、星灯りが戻った。<small>あなたの冒険は、これからも続いていく。</small>':`${z.name}<small>${['やわらかな風が、冒険のはじまりを告げる。','月明かりの下、忘れられた記憶が眠る。','灰の向こうで、竜の咆哮が響く。'][state.zone]}</small>`;
$('commandTitle').textContent=e?`${e.name}が こちらを見ている！`:state.village?'おかえりなさい、アステル。':'次はどこへ向かいますか？';$('turn').textContent=e?'TURN '+state.turn:'';
$('actions').innerHTML=e?btn('⚔ こうげき','attack','ATTACK',busy)+btn('✧ スキル','skills','SKILL',busy)+btn('♧ どうぐ','items','ITEM',busy)+btn('♢ ぼうぎょ','guard','DEFEND',busy):state.village?btn('☽ 宿屋で休む','rest','10 G / FULL HEAL')+btn('⚒ お店','shop','SHOP')+btn('✧ 依頼の報酬','claim','QUEST',state.total<5||state.claimed)+btn('→ 冒険へ','leave','DEPART'):btn('⚔ 探索する','explore','EXPLORE')+btn('♜ ボスに挑む','boss','BOSS',state.kills[state.zone]<z.kills||state.cleared[state.zone])+btn('♧ 回復する','items','RECOVER')+btn('⌂ 村へ戻る','village','VILLAGE');
$('regions').innerHTML=zones.map((a,i)=>`<button class="region ${state.zone===i?'selected':''}" data-action="zone:${i}" ${e||busy||i>0&&!state.cleared[i-1]?'disabled':''}><span class="icon">${a.icon}</span><span><strong>${a.name}</strong><small>${i>0&&!state.cleared[i-1]?'前のエリアをクリアで解放':a.sub}</small></span><span class="check">${state.cleared[i]?'✓':i>0&&!state.cleared[i-1]?'⌑':'›'}</span></button>`).join('');$('camp').disabled=!!e||busy;
const q=state.cleared.findIndex(x=>!x);$('questTitle').textContent=q===-1?'星灯りを取り戻した':`${['草原の守り手','遺跡の秘密','最後の星のかけら'][q]}`;$('questText').textContent=q===-1?'三つの星のかけらがひとつに。世界に夜明けが訪れました。':`${zones[q].name}の魔物を${zones[q].kills}体倒し、${zones[q].boss}に挑もう。`;$('questProgress').innerHTML=q===-1?'<small>✧ MAIN QUEST COMPLETE</small>':`<div class="bar exp"><i style="width:${Math.min(100,state.kills[q]/zones[q].kills*100)}%"></i></div><p><small>討伐 ${Math.min(state.kills[q],zones[q].kills)} / ${zones[q].kills}　${state.kills[q]>=zones[q].kills?'ボス戦 解放！':''}</small></p>`;$('log').innerHTML=state.log.map(t=>'<p>› '+t+'</p>').join('');renderInventory();save()}
function renderInventory(){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));if(tab==='skills'){$('inventory').innerHTML=skillList.map(s=>`<div class="item"><span class="itemicon">${s.icon}</span><div><strong>${s.name}</strong><small>${state.lv<s.lv?`Lv.${s.lv}で習得`:s.desc+' · MP '+s.cost}</small></div>${s.id==='heal'&&state.lv>=3?btn('使う','skill:heal','',busy||state.mp<5):`<span class="count">${state.lv>=s.lv?'✓':'⌑'}</span>`}</div>`).join('');return}
if(tab==='shop'){$('inventory').innerHTML='<p>⌂ はじまりの村の道具・武器屋<br>村に戻ると購入できます。</p>'+Object.entries(consumables).map(([id,a])=>itemRow(a,`${a.desc}`,btn(a.price+' G','buy:'+id,'',!state.village||state.gold<a.price))).join('')+Object.entries(gear).filter(([,g])=>g.price).map(([id,a])=>itemRow(a,`${a.type==='weapon'?'攻撃':'守備'} +${a.value}`,btn(state.owned.includes(id)?'購入済':a.price+' G','buy:'+id,'',!state.village||state.gold<a.price||state.owned.includes(id)))).join('');return}
$('inventory').innerHTML=Object.entries(consumables).map(([id,a])=>itemRow(a,`${a.desc} · ${state.items[id]} 個`,btn('使う','use:'+id,'',busy||!state.items[id]))).join('')+'<p style="border-top:1px solid #344148;padding-top:14px">装備品</p>'+state.owned.map(id=>{const a=gear[id],equipped=state[a.type]===id;return itemRow(a,`${a.type==='weapon'?'攻撃':'守備'} +${a.value}`,btn(equipped?'装備中':'装備','equip:'+id,'',equipped||!!state.enemy||busy))}).join('')}
function itemRow(a,desc,button){return `<div class="item"><span class="itemicon">${a.icon}</span><div><strong>${a.name}</strong><small>${desc}</small></div>${button}</div>`}
function startBattle(boss=false){if(state.enemy||state.village||busy)return;const z=state.zone;if(boss&&(state.kills[z]<4||state.cleared[z]))return;const n=z*3+1+Math.floor(Math.random()*2),max=boss?[130,240,390][z]:30+n*9;state.enemy={name:boss?zones[z].boss:[['リーフジェリー','こけ玉'],['ミストジェリー','遺跡の精霊'],['マグマジェリー','火の精霊']][z][n%2],hp:max,max,atk:boss?[20,32,44][z]:8+n*3,def:boss?4+z*4:1+z*3,xp:boss?80+z*60:18+z*18,gold:boss?70+z*60:10+z*12,boss};state.turn=1;log(`${state.enemy.name}が あらわれた！`);$('subactions').innerHTML='';render()}
async function combat(kind){if(!state.enemy||busy)return;if(kind==='run'){if(state.enemy.boss){log('ボスからは逃げられない！');render();return}if(Math.random()<.7){log('うまく逃げきった。');state.enemy=null;render();return}}busy=true;let guard=kind==='guard';if(kind==='attack'){const critical=Math.random()<.12;const dmg=Math.max(2,Math.floor(attack()*(critical?1.8:1)+Math.random()*5-state.enemy.def));state.enemy.hp=Math.max(0,state.enemy.hp-dmg);log(`${critical?'会心の一撃！ ':''}${dmg}のダメージ！`);hit(dmg)}else if(guard)log('身を守り、MPが3回復した。');if(guard)state.mp=Math.min(maxmp(),state.mp+3);beep();render();if(state.enemy.hp<=0){win();busy=false;render();return}await new Promise(r=>setTimeout(r,430));if(state.enemy){let damage=Math.max(1,Math.floor(state.enemy.atk+(Math.random()*7)-defense()*.65));const strong=state.turn%3===0;if(strong)damage=Math.floor(damage*1.4);if(guard)damage=Math.max(1,Math.floor(damage*.35));state.hp=Math.max(0,state.hp-damage);log(`${state.enemy.name}の${strong?'強攻撃':'攻撃'}！ ${damage}のダメージ。`);state.turn++;if(state.hp<=0){const lost=Math.floor(state.gold*.15);state.gold-=lost;state.enemy=null;state.village=true;state.hp=maxhp();state.mp=maxmp();log(`村で目を覚ました。救助費${lost} G。経験値と装備は無事だ。`);modal('まだ、旅は終わらない','村の人に助けられました。HP・MPが回復しました。装備を整え、もう一度挑んでみましょう。')}}busy=false;render()}
function hit(n){$('enemy').classList.add('hit');setTimeout(()=>$('enemy').classList.remove('hit'),300)}
function win(){const e=state.enemy;state.enemy=null;state.total++;state.kills[state.zone]++;state.xp+=e.xp;state.gold+=e.gold;log(`${e.name}を倒した！ ${e.xp} EXP・${e.gold} Gを獲得。`);if(e.boss){state.cleared[state.zone]=true;state.hp=maxhp();state.mp=maxmp();log('星のかけらを手に入れた！ HP・MPが全回復。');modal(state.zone===2?'✧ 星灯りは、ふたたび世界へ':'✧ 星のかけらを手に入れた',state.zone===2?'三つのかけらが輝き、長い夜が明けました。アステルの勇気は、人々の新しい物語になります。クリアおめでとう！ このまま冒険を続けられます。':'新しいエリアが解放されました。地図から次の旅へ進みましょう。')}else if(Math.random()<.5){state.items.herb++;log('いやし草を拾った！')}if(!e.boss&&Math.random()<.13){const id=state.zone===0?'iron':state.zone===1?'leather':'star';if(!state.owned.includes(id)){state.owned.push(id);log(`${gear[id].name}を発見！ もちものから装備できる。`)}else{state.items.ether++;log('星のしずくを拾った！')}}while(state.xp>=threshold()&&state.lv<30){state.xp-=threshold();state.lv++;state.hp=maxhp();state.mp=maxmp();log(`レベル${state.lv}にアップ！ 能力上昇・HPとMPが全回復！`);const s=skillList.find(s=>s.lv===state.lv);if(s)log(`新スキル「${s.name}」を覚えた！`)}$('subactions').innerHTML='';beep(1)}
function useItem(id){if(busy||!consumables[id]||state.items[id]<=0)return;const mp=id==='ether';if((mp?state.mp>=maxmp():state.hp>=maxhp())){log(`${mp?'MP':'HP'}は満タンです。`);render();return}state.items[id]--;if(mp)state.mp=Math.min(maxmp(),state.mp+18);else state.hp=Math.min(maxhp(),state.hp+(id==='herb'?45:maxhp()));log(`${consumables[id].name}を使った。${mp?'MP':'HP'}が回復！`);$('subactions').innerHTML='';if(state.enemy)combat('item');else render()}
function useSkill(id){const s=skillList.find(x=>x.id===id);if(!s||state.lv<s.lv||state.mp<s.cost||busy)return;if(id!=='heal'&&!state.enemy)return;if(id==='heal'&&state.hp>=maxhp()){log('HPは満タンです。');render();return}state.mp-=s.cost;if(id==='heal'){state.hp=Math.min(maxhp(),state.hp+55);log('星のいやし！ HPが55回復。')}else{const dmg=id==='flame'?24+state.lv*5:id==='slash'?Math.max(1,Math.floor(attack()*2.4-state.enemy.def)):65+state.lv*9;state.enemy.hp=Math.max(0,state.enemy.hp-dmg);log(`${s.name}！ ${dmg}のダメージ！`)}$('subactions').innerHTML='';if(state.enemy)combat('skill');else render()}
function modal(title,body){$('modalContent').innerHTML=`<h2>${title}</h2><p>${body}</p>`;$('modal').showModal()}
function action(a){if(busy)return;const [key,id]=a.split(':');switch(key){case'explore':startBattle();break;case'boss':startBattle(true);break;case'attack':case'guard':case'run':combat(key);break;case'skills':$('subactions').innerHTML=skillList.filter(s=>state.lv>=s.lv).map(s=>btn(s.name+' · MP '+s.cost,'skill:'+s.id,'',state.mp<s.cost)).join('')||'<p class="muted">Lv.2で最初のスキルを習得します。</p>';break;case'items':$('subactions').innerHTML=Object.entries(consumables).map(([k,v])=>btn(`${v.name} ×${state.items[k]}`,'use:'+k,'',!state.items[k])).join('')+(state.enemy?btn('逃げる','run','',state.enemy.boss):'');break;case'use':useItem(id);break;case'skill':useSkill(id);break;case'village':if(state.enemy)return;state.village=true;$('subactions').innerHTML='';log('はじまりの村に帰ってきた。宿屋で休もう。');render();break;case'leave':state.village=false;render();break;case'rest':if(!state.village)return;if(state.gold<10){log('宿代が足りない。村人の厚意でHP・MPが半分まで回復。');state.hp=Math.max(state.hp,Math.ceil(maxhp()/2));state.mp=Math.max(state.mp,Math.ceil(maxmp()/2))}else{state.gold-=10;state.hp=maxhp();state.mp=maxmp();log('宿屋でひと休み。HP・MPが全回復！')}render();break;case'zone':if(state.enemy||!zones[id]||(+id>0&&!state.cleared[id-1]))return;state.zone=+id;state.village=false;$('subactions').innerHTML='';render();break;case'shop':tab='shop';renderInventory();break;case'buy':{if(!state.village)return;const item=consumables[id]||gear[id];if(!item||state.gold<item.price||gear[id]&&state.owned.includes(id))return;state.gold-=item.price;if(consumables[id])state.items[id]++;else state.owned.push(id);log(`${item.name}を購入した。`);render();break}case'equip':if(state.enemy||!state.owned.includes(id))return;state[gear[id].type]=id;log(`${gear[id].name}を装備した。`);render();break;case'claim':if(!state.village||state.claimed||state.total<5)return;state.claimed=true;state.gold+=100;state.items.potion+=2;log('村長の依頼達成！ 100 Gと生命の霊薬2個を受け取った。');render();break}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)action(b.dataset.action);const t=e.target.closest('[data-tab]');if(t){tab=t.dataset.tab;renderInventory()}});$('camp').onclick=()=>action('village');$('sound').onclick=()=>{sound=!sound;$('sound').textContent='♫ 音 '+(sound?'ON':'OFF');beep(1)};$('closeModal').onclick=()=>$('modal').close();$('help').onclick=()=>modal('冒険の手引き','「探索する」で魔物とバトル。1回行動すると敵も行動します。3ターン目ごとの強攻撃には「ぼうぎょ」が有効です（MPも回復）。<br><br>経験値でレベルアップし、Lv.2・3・5・7でスキルを習得。各地で4体倒すとボスに挑めます。ボスを倒すと次のエリアへ進めます。<br><br>村では10 Gで宿泊、装備や道具を購入できます。装備は購入後に「もちもの」から装着。5体討伐で村長から100 Gと霊薬2個の報酬も。全滅しても村で復活します。<br><br>進行はこのブラウザへ自動保存。別の端末とは同期されません。');$('reset').onclick=()=>{modal('冒険をやり直しますか？','このブラウザに保存した進行を消し、Lv.1から始めます。');const b=document.createElement('button');b.textContent='進行を消して最初から';b.onclick=()=>{state=initial();busy=false;$('subactions').innerHTML='';$('modal').close();render()};$('modalContent').append(b)};render();
